<?php use App\Support\Ui; $isToday=$selected->format('Y-m-d')===$today->format('Y-m-d');$openMin=(int)substr($hours['opens_at'],0,2)*60+(int)substr($hours['opens_at'],3,2);$closeMin=(int)substr($hours['closes_at'],0,2)*60+(int)substr($hours['closes_at'],3,2);$nowMin=(int)$today->format('H')*60+(int)$today->format('i'); ?>
<div class="page-heading admin-heading"><div><span class="eyebrow">RESOURCE SCHEDULE</span><h1>Operations calendar</h1><p><?= $view==='day'?$e($selected->format('l, d F Y')):$e($from->format('d M').' – '.$to->modify('-1 day')->format('d M Y')) ?></p></div><a class="button primary" href="<?= $e($url('admin/interview/new?date='.$selected->format('Y-m-d'))) ?>"><?= Ui::icon('plus') ?>New interview</a></div>
