<?php if(!$hours['is_open']): ?>
<section class="card empty-state calendar-empty"><div class="empty-icon"><?= Ui::icon('calendar') ?></div><h2>Operations are closed on this day.</h2><p>Business hours are controlled in Scheduling settings.</p><a class="button secondary" href="<?= $e($url('admin/settings')) ?>">View settings</a></section>
<?php elseif(!$resources): ?>
