<?php else: ?>
<section class="calendar-card card"><div class="lane-header"><span>IST</span><div class="lane-headings"><?php foreach($resources as $resource): ?><div><strong><?= $e($resource['name']) ?></strong><small><?= $e(ucfirst(strtolower($resource['resource_type']))) ?></small></div><?php endforeach; ?></div></div><div class="lane-body"><div class="time-axis"><?php for($m=$openMin;$m<$closeMin;$m+=15): ?><span><?= $m%30===0?$e(sprintf('%02d:%02d',intdiv($m,60),$m%60)):'' ?></span><?php endfor; ?></div><div class="lanes-area"><?php foreach($resources as $resource): ?><div class="resource-lane"><?php for($m=$openMin;$m<$closeMin;$m+=15): ?><div class="calendar-cell"><?php if($isToday&&$nowMin>=$m&&$nowMin<$m+15): ?><span class="now-segment"><?= $resource===$resources[0]?'Now':'' ?></span><?php endif; ?><?php foreach($interviews as $item): $itemMin=(int)$item['start_local']->format('H')*60+(int)$item['start_local']->format('i');if((int)$item['resource_id']!==(int)$resource['id']||$itemMin!==$m)continue; ?><button class="calendar-event duration-<?= $e($item['duration_minutes']) ?> <?= $item['interview_type']==='TOOL'?'tool':'normal' ?> <?= $item['end_local']<$today&&$isToday?'elapsed':'' ?> <?= $item['candidate_deleted']?'deleted-candidate-event':'' ?>" data-calendar-card data-id="<?= $e($item['id']) ?>" data-name="<?= $e($item['candidate_name'].($item['candidate_deleted']?' · Deleted candidate':'')) ?>" data-company="<?= $e($item['company_name']) ?>" data-time="<?= $e($item['display_time']) ?>" data-resource="<?= $e($item['resource_name']) ?>" data-support="<?= $e($item['support_person_name']??'Not required') ?>"><strong><?= $e($item['start_local']->format('g:i')) ?> · <?= $e($item['candidate_name']) ?></strong><span><?= $e($item['company_name']) ?></span><small><?= $item['candidate_deleted']?'Deleted candidate · ':'' ?><?= $e($item['support_person_name']??$item['technology_name']) ?></small></button><?php endforeach; ?></div><?php endfor; ?></div><?php endforeach; ?></div></div></section>
<section class="mobile-agenda card"><div class="card-heading"><h2>Agenda</h2><span class="badge neutral"><?= count($interviews) ?> bookings</span></div><?php if(!$interviews): ?><div class="empty-state"><h3>No interviews are scheduled for today.</h3></div><?php else: ?><div class="agenda-list"><?php foreach($interviews as $item): ?><button class="agenda-row" data-calendar-card data-id="<?= $e($item['id']) ?>" data-name="<?= $e($item['candidate_name'].($item['candidate_deleted']?' · Deleted candidate':'')) ?>" data-company="<?= $e($item['company_name']) ?>" data-time="<?= $e($item['display_time']) ?>" data-resource="<?= $e($item['resource_name']) ?>" data-support="<?= $e($item['support_person_name']??'Not required') ?>"><time><?= $e($item['start_local']->format('g:i A')) ?></time><div><strong><?= $e($item['candidate_name']) ?><?php if($item['candidate_deleted']):?><span class="deleted-label">Deleted candidate</span><?php endif;?></strong><small><?= $e($item['company_name']) ?> · <?= $e($item['technology_name']) ?></small><small><?= $e($item['resource_name']) ?><?= $item['support_person_name']?' · '.$e($item['support_person_name']):'' ?></small></div></button><?php endforeach; ?></div><?php endif; ?></section>
<?php endif; ?>
<?php else: ?>
<section class="week-grid"><?php for($d=0;$d<7;$d++):$day=$from->modify("+$d days");$dayRows=array_filter($interviews,fn($i)=>$i['start_local']->format('Y-m-d')===$day->format('Y-m-d'));$closed=!($weekHours[(int)$day->format('N')]??false);?><article class="card week-day <?= $day->format('Y-m-d')===$today->format('Y-m-d')?'today':'' ?> <?= $closed?'closed':'' ?>"><header><span><?= $e($day->format('D')) ?></span><strong><?= $e($day->format('d')) ?></strong></header><?php if($closed):?><p class="week-empty">Closed</p><?php elseif(!$dayRows): ?><p class="week-empty">No interviews</p><?php else: ?><?php foreach($dayRows as $item): ?><a href="<?= $e($url('admin/interview?id='.$item['id'])) ?>"><time><?= $e($item['start_local']->format('g:i A')) ?></time><strong><?= $e($item['candidate_name']) ?><?php if($item['candidate_deleted']):?><span class="deleted-label">Deleted candidate</span><?php endif;?></strong><small><?= $e($item['resource_name']) ?></small></a><?php endforeach; ?><?php endif; ?></article><?php endfor; ?></section>
<?php endif; ?>
